_cleanups = []

def _add_cleanup(f, *args, **kwargs):
    _cleanups.append((f, args, kwargs))

def _run_cleanups():
    while _cleanups:
        f, args, kwargs = _cleanups.pop()
        f(*args, **kwargs)
from test.support import import_helper
resource = import_helper.import_module('resource')

def _t():
    cur, max = resource.getrlimit(resource.RLIMIT_FSIZE)
    _add_cleanup(resource.setrlimit, *(resource.RLIMIT_FSIZE, (cur, max)))

    def expected(cur):
        if resource.RLIM_INFINITY < 0:
            return [(cur, max), (resource.RLIM_INFINITY, max)]
        elif resource.RLIM_INFINITY < cur:
            return [(resource.RLIM_INFINITY, max)]
        else:
            return [(cur, max)]
    resource.setrlimit(resource.RLIMIT_FSIZE, (2 ** 31 - 5, max))
    assert resource.getrlimit(resource.RLIMIT_FSIZE) == (2 ** 31 - 5, max), ('assertEqual', resource.getrlimit(resource.RLIMIT_FSIZE), (2 ** 31 - 5, max))
    try:
        resource.setrlimit(resource.RLIMIT_FSIZE, (2 ** 32, max))
    except OverflowError:
        resource.setrlimit(resource.RLIMIT_FSIZE, (2 ** 31, max))
        assert resource.getrlimit(resource.RLIMIT_FSIZE) in expected(2 ** 31), ('assertIn', resource.getrlimit(resource.RLIMIT_FSIZE), expected(2 ** 31))
        resource.setrlimit(resource.RLIMIT_FSIZE, (2 ** 32 - 5, max))
        assert resource.getrlimit(resource.RLIMIT_FSIZE) in expected(2 ** 32 - 5), ('assertIn', resource.getrlimit(resource.RLIMIT_FSIZE), expected(2 ** 32 - 5))
    else:
        assert resource.getrlimit(resource.RLIMIT_FSIZE) in expected(2 ** 32), ('assertIn', resource.getrlimit(resource.RLIMIT_FSIZE), expected(2 ** 32))
        resource.setrlimit(resource.RLIMIT_FSIZE, (2 ** 31, max))
        assert resource.getrlimit(resource.RLIMIT_FSIZE) == (2 ** 31, max), ('assertEqual', resource.getrlimit(resource.RLIMIT_FSIZE), (2 ** 31, max))
        resource.setrlimit(resource.RLIMIT_FSIZE, (2 ** 32 - 5, max))
        assert resource.getrlimit(resource.RLIMIT_FSIZE) == (2 ** 32 - 5, max), ('assertEqual', resource.getrlimit(resource.RLIMIT_FSIZE), (2 ** 32 - 5, max))
        resource.setrlimit(resource.RLIMIT_FSIZE, (2 ** 63 - 5, max))
        assert resource.getrlimit(resource.RLIMIT_FSIZE) in expected(2 ** 63 - 5), ('assertIn', resource.getrlimit(resource.RLIMIT_FSIZE), expected(2 ** 63 - 5))
        try:
            resource.setrlimit(resource.RLIMIT_FSIZE, (2 ** 63, max))
        except ValueError:
            pass
        else:
            assert resource.getrlimit(resource.RLIMIT_FSIZE) in expected(2 ** 63), ('assertIn', resource.getrlimit(resource.RLIMIT_FSIZE), expected(2 ** 63))
            resource.setrlimit(resource.RLIMIT_FSIZE, (2 ** 64 - 5, max))
            assert resource.getrlimit(resource.RLIMIT_FSIZE) in expected(2 ** 64 - 5), ('assertIn', resource.getrlimit(resource.RLIMIT_FSIZE), expected(2 ** 64 - 5))
try:
    _t()
except BaseException as _e:
    print('ORACLE_EXC ' + type(_e).__name__ + ' ' + repr(str(_e)))
else:
    print('ok')
finally:
    _run_cleanups()

